mapper.select:
SELECT record_type,COUNT(*) record_count,
       COALESCE(SUM(CASE WHEN created_role='FARM_CARE_MANAGER' THEN 1 ELSE 0 END),0) manager_input_count
FROM (
    SELECT 'WORK' record_type,created_role FROM work_log WHERE farm_id=#{farmId} AND deleted_at IS NULL AND work_date>=#{start} AND work_date<#{endExclusive}
    UNION ALL SELECT 'PEST_CONTROL',created_role FROM pest_control_log WHERE farm_id=#{farmId} AND deleted_at IS NULL AND apply_date>=#{start} AND apply_date<#{endExclusive}
    UNION ALL SELECT 'HARVEST',created_role FROM harvest_log WHERE farm_id=#{farmId} AND deleted_at IS NULL AND harvest_date>=#{start} AND harvest_date<#{endExclusive}
    UNION ALL SELECT 'SALES',created_role FROM sales_log WHERE farm_id=#{farmId} AND deleted_at IS NULL AND sales_date>=#{start} AND sales_date<#{endExclusive}
) records GROUP BY record_type

SELECT farm_id,record_type,COUNT(*) record_count,COALESCE(SUM(CASE WHEN created_role='FARM_CARE_MANAGER' THEN 1 ELSE 0 END),0) manager_input_count FROM (
  SELECT farm_id,'WORK' record_type,created_role FROM work_log WHERE farm_id AND deleted_at IS NULL AND work_date>=#{start} AND work_date<#{endExclusive}
  UNION ALL SELECT farm_id,'PEST_CONTROL',created_role FROM pest_control_log WHERE farm_id AND deleted_at IS NULL AND apply_date>=#{start} AND apply_date<#{endExclusive}
  UNION ALL SELECT farm_id,'HARVEST',created_role FROM harvest_log WHERE farm_id AND deleted_at IS NULL AND harvest_date>=#{start} AND harvest_date<#{endExclusive}
  UNION ALL SELECT farm_id,'SALES',created_role FROM sales_log WHERE farm_id AND deleted_at IS NULL AND sales_date>=#{start} AND sales_date<#{endExclusive}
) r GROUP BY farm_id,record_type ORDER BY farm_id,record_type

SELECT farm_id,LOWER(TRIM(unit)) unit,SUM(quantity) sold_quantity,SUM(gross_amount) gross_sales_amount
FROM sales_log WHERE farm_id AND deleted_at IS NULL AND sales_date>=#{start} AND sales_date<#{endExclusive}
GROUP BY farm_id,LOWER(TRIM(unit)) HAVING SUM(quantity)>0 ORDER BY farm_id,unit
